async function plan({ posts, includes }, context) {
  if (!Array.isArray(posts)) throw Error("Missing X results");
  if (posts.length && (!includes || !Array.isArray(includes.users)))
    throw Error("Missing expanded authors");
  const prev = await context.state.get("x-search-ids");
  if (prev !== null && !Array.isArray(prev)) throw Error("Invalid previous IDs");
  const ids = [],
    queue = [];
  for (const p of posts) {
    const raw = p.raw ?? p,
      id = p.id,
      text = p.text,
      authorId = p.authorId ?? raw.author_id;
    if (typeof id !== "string" || !id || typeof text !== "string" || typeof authorId !== "string")
      throw Error("Incomplete X post");
    ids.push(id);
    const u = includes.users.find((x) => x.id === authorId);
    if (!u || typeof u.username !== "string" || !u.username || typeof u.name !== "string")
      throw Error("Missing X author");
    queue.push({ id, text, username: u.username, name: u.name, photo: u.profile_image_url ?? "" });
  }
  let pending = [];
  for (const x of queue) {
    if (prev?.includes(x.id)) break;
    pending.push(x);
  }
  return { pending, ids, hasResults: ids.length > 0 };
}

const input = $input.first().json,
  store = $getWorkflowStaticData("global");
const p = await plan(
  { posts: input.data ?? [], includes: input.includes ?? { users: [] } },
  { state: { get: async () => store.ids ?? null } },
);
if (p.hasResults) store.ids = p.ids;
return p.pending.map((x, i) => ({ json: x, pairedItem: { item: 0 } }));
